/**
 * Person renderer — atlas-driven animated characters.
 *
 * The atlas (`/assets/office/atlas.png` + `.json`, generated by
 * `infra/scripts/make_character_atlas.py`) holds 8 looks x 4 facings with
 * 4-frame walk cycles, 2-frame idle breathing, 2-frame typing and seated
 * poses. Frame selection:
 *
 *   walk   — `stride` (0..1, distance-synced) picks the frame, so feet
 *            plant exactly when the frames show a planted foot
 *   idle   — 2-frame breathing loop on the shared animPhase clock
 *   type   — 2-frame hand alternation (faster clock when working)
 *   sit    — single seated pose per facing (meeting room)
 *
 * Legacy single-pose archetype PNGs remain as a fallback; below that,
 * a procedural pixel person renders so the office is never empty.
 */

import { tint } from './IsoMath'
import { ATLAS_FRAMES, type AtlasFrame } from './atlasFrames.generated'
import type { SimEmployee } from '../systems/Types'

export type CharacterSpriteMap = Record<string, HTMLImageElement>

export interface AtlasSheet {
  img: HTMLImageElement
  frames: Record<string, AtlasFrame>
}

const ATLAS_PNG = '/assets/office/characters/atlas.png'

/**
 * Load the animated atlas PNG. The frame table is a generated TS module
 * (`atlasFrames.generated.ts`) — the office performs no network requests, so
 * is compile-time data, not a runtime request.
 */
export async function loadAtlas(): Promise<AtlasSheet | null> {
  try {
    const img = new Image()
    await new Promise<void>((resolve, reject) => {
      img.onload = () => resolve()
      img.onerror = () => reject(new Error('atlas.png failed'))
      img.src = ATLAS_PNG
    })
    return { img, frames: ATLAS_FRAMES }
  } catch {
    return null
  }
}

/**
 * Preload legacy archetype sprites (fallback path when the atlas is absent).
 */
export async function loadCharacterSprites(): Promise<CharacterSpriteMap> {
  const map: CharacterSpriteMap = {}
  const poses = ['idle', 'working']
  const archetypes = [
    'exec',
    'manager',
    'senior_engineer',
    'engineer',
    'intern',
    'devops',
  ]
  const promises: Promise<void>[] = []
  for (const arch of archetypes) {
    for (const pose of poses) {
      const key = `${arch}_${pose}`
      const img = new Image()
      img.src = `/assets/office/characters/${key}.png`
      promises.push(
        new Promise<void>((resolve) => {
          img.onload = () => {
            map[key] = img
            resolve()
          }
          img.onerror = () => resolve()
        }),
      )
    }
  }
  await Promise.all(promises)
  return map
}

/* ── Frame selection ─────────────────────────────────────────────────── */

const DIRS: Record<string, 'n' | 'e' | 's' | 'w'> = { n: 'n', e: 'e', s: 's', w: 'w' }

function pickAtlasFrame(e: SimEmployee): { name: string; sheet: AtlasSheet } | null {
  const sheet = atlasRef.sheet
  if (!sheet) return null
  const look = e.look ?? hashLook(e.id)
  const dir = DIRS[e.facing] ?? 's'

  if (e.activity === 'sit') {
    const name = `look_${look}_sit_${dir === 'n' ? 'n' : 's'}`
    return sheet.frames[name] ? { name, sheet } : null
  }
  if (e.animKind === 'walk') {
    const f = Math.floor(e.stride * 4) % 4
    const name = `look_${look}_walk_${dir}_${f}`
    return sheet.frames[name] ? { name, sheet } : null
  }
  if (e.animKind === 'type') {
    const f = Math.floor(e.animPhase) % 2
    const name = `look_${look}_type_${dir}_${f}`
    return sheet.frames[name] ? { name, sheet } : null
  }
  const f = Math.floor(e.animPhase) % 2
  const name = `look_${look}_idle_${dir}_${f}`
  return sheet.frames[name] ? { name, sheet } : null
}

function hashLook(id: string): number {
  let h = 0
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) | 0
  return Math.abs(h) % 8
}

/** Shared atlas handle (set by OfficeSimulation at boot). */
const atlasRef: { sheet: AtlasSheet | null } = { sheet: null }

export function setAtlas(sheet: AtlasSheet | null): void {
  atlasRef.sheet = sheet
}

/* ── Drawing ─────────────────────────────────────────────────────────── */

function drawProceduralPerson(
  c: CanvasRenderingContext2D,
  wx: number,
  wy: number,
  e: SimEmployee,
): void {
  const kind = e.animKind || 'idle'
  const ph = e.animPhase || 0
  const facing = e.facing || 'e'

  let bob = 0
  let liftL = 0
  let liftR = 0

  if (kind === 'walk') {
    const w = Math.sin(ph)
    bob = Math.abs(w) * 1.6
    liftL = Math.max(0, w) * 3.2
    liftR = Math.max(0, -w) * 3.2
  } else if (kind === 'type') {
    bob = Math.sin(ph * 0.4) * 0.4
  } else {
    bob = Math.sin(ph * 0.5) * 0.5
  }

  c.save()
  c.translate(wx, wy - bob)

  c.fillStyle = 'rgba(0,0,0,.28)'
  c.beginPath()
  c.ellipse(0, 0, 13, 6, 0, 0, Math.PI * 2)
  c.fill()

  const dark = (col: string) => tint(col, 0.72)

  c.fillStyle = '#2B3446'
  c.fillRect(-8, -14 + liftL, 6, 14 - liftL)
  c.fillRect(2, -14 + liftR, 6, 14 - liftR)

  c.fillStyle = '#171C26'
  c.fillRect(-7, -2 + liftL, 7, 3)
  c.fillRect(1, -2 + liftR, 7, 3)

  c.fillStyle = e.shirt
  c.fillRect(-10, -31, 20, 18)
  c.fillStyle = tint(e.shirt, 1.18)
  c.fillRect(-10, -31, 20, 3)

  c.fillStyle = dark(e.shirt)
  c.fillRect(-13, -29, 4, 13)
  c.fillRect(9, -29, 4, 13)

  c.fillStyle = e.skin
  c.fillRect(-3, -34, 6, 4)
  c.fillRect(-8, -47, 16, 14)

  c.fillStyle = e.hair
  c.fillRect(-9, -49, 18, 7)
  c.fillRect(-9, -43, 3, 4)
  c.fillRect(6, -43, 3, 4)

  const eyeShift = facing === 'e' ? 1 : facing === 'w' ? -1 : 0
  if (facing !== 'n') {
    c.fillStyle = '#1B1B22'
    c.fillRect(-5 + eyeShift, -41, 2, 2)
    c.fillRect(2 + eyeShift, -41, 2, 2)
  }

  c.restore()
}

function drawLegacySprite(
  c: CanvasRenderingContext2D,
  wx: number,
  wy: number,
  e: SimEmployee,
  sprites: CharacterSpriteMap,
): boolean {
  const isWorking = e.fsm === 'working' || e.animKind === 'type'
  const pose = isWorking ? 'working' : 'idle'
  const arch = e.archetype || 'engineer'
  const img = sprites[`${arch}_${pose}`]
  if (!img) return false

  const bob = Math.sin(e.animPhase * 0.5) * 0.5
  c.fillStyle = 'rgba(0,0,0,.28)'
  c.beginPath()
  c.ellipse(wx, wy, 13, 6, 0, 0, Math.PI * 2)
  c.fill()
  c.drawImage(img, Math.round(wx - img.width / 2), Math.round(wy - img.height - bob))
  return true
}

/**
 * Draw one person at world-feet position (wx, wy), depth-sorted by caller.
 */
export function drawPerson(
  c: CanvasRenderingContext2D,
  wx: number,
  wy: number,
  e: SimEmployee,
  sprites?: CharacterSpriteMap,
): void {
  // Grounding shadow — drawn for every path so all bodies ground the same way.
  c.fillStyle = 'rgba(0,0,0,.28)'
  c.beginPath()
  c.ellipse(wx, wy, 12, 5.5, 0, 0, Math.PI * 2)
  c.fill()

  const picked = pickAtlasFrame(e)
  if (picked) {
    const f = picked.sheet.frames[picked.name]!
    // Feet anchor (32, 62) inside the 64x64 cell.
    c.drawImage(
      picked.sheet.img,
      f.frame.x,
      f.frame.y,
      f.frame.w,
      f.frame.h,
      Math.round(wx - f.anchor.x),
      Math.round(wy - f.anchor.y),
      f.frame.w,
      f.frame.h,
    )
    if (e.bubble) drawBubble(c, wx, wy - 66, e.bubble.text)
    return
  }

  if (sprites && drawLegacySprite(c, wx, wy, e, sprites)) {
    if (e.bubble) drawBubble(c, wx, wy - 60, e.bubble.text)
    return
  }

  drawProceduralPerson(c, wx, wy, e)
  if (e.bubble) drawBubble(c, wx, wy - 60, e.bubble.text)
}

/* ── Speech bubbles ──────────────────────────────────────────────────── */

function drawBubble(c: CanvasRenderingContext2D, wx: number, wy: number, text: string): void {
  c.save()
  c.font = '600 10px "Archivo", system-ui, sans-serif'
  const tw = Math.min(150, c.measureText(text).width)
  const padX = 7
  const bw = Math.ceil(tw) + padX * 2
  const bh = 18
  const x = Math.round(wx - bw / 2)
  const y = Math.round(wy - bh - 6)

  c.globalAlpha = 0.96
  c.fillStyle = 'rgba(244,248,255,0.97)'
  roundRect(c, x, y, bw, bh, 6)
  c.fill()
  c.strokeStyle = 'rgba(15,23,42,0.25)'
  c.lineWidth = 1
  roundRect(c, x + 0.5, y + 0.5, bw - 1, bh - 1, 6)
  c.stroke()

  // tail
  c.fillStyle = 'rgba(244,248,255,0.97)'
  c.beginPath()
  c.moveTo(wx - 4, y + bh)
  c.lineTo(wx + 4, y + bh)
  c.lineTo(wx, y + bh + 5)
  c.closePath()
  c.fill()

  c.fillStyle = '#0F172A'
  c.textAlign = 'center'
  c.textBaseline = 'middle'
  c.fillText(text, x + bw / 2, y + bh / 2 + 0.5, 150)
  c.restore()
}

function roundRect(
  c: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): void {
  c.beginPath()
  c.moveTo(x + r, y)
  c.arcTo(x + w, y, x + w, y + h, r)
  c.arcTo(x + w, y + h, x, y + h, r)
  c.arcTo(x, y + h, x, y, r)
  c.arcTo(x, y, x + w, y, r)
  c.closePath()
}

/* ── Halos ───────────────────────────────────────────────────────────── */

export function getHaloRadii(_e: SimEmployee, _sprites?: CharacterSpriteMap): [number, number] {
  return [17, 8.5]
}

export function drawHalo(
  c: CanvasRenderingContext2D,
  wx: number,
  wy: number,
  color: string,
  pulse: number,
  radiusX = 17,
  radiusY = 8.5,
): void {
  c.save()
  c.translate(wx, wy)
  c.globalAlpha = pulse
  c.strokeStyle = color
  c.lineWidth = 2
  c.beginPath()
  c.ellipse(0, 0, radiusX, radiusY, 0, 0, Math.PI * 2)
  c.stroke()
  c.globalAlpha = pulse * 0.14
  c.fillStyle = color
  c.fill()
  c.restore()
}
